function g({registerIndicator:y,nulls:r}){y({id:"oa-eri",name:"Elder Ray Index (ERI)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:13,min:1,max:500,step:1}],plots:[{key:"bull",type:"line",title:"Bull Power",style:{color:"#4caf50",lineWidth:2}},{key:"bear",type:"line",title:"Bear Power",style:{color:"#ff5252",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#9598a1",dashed:!0}],calc(t,b){const a=2/(Math.min(500,Math.max(1,Math.floor(Number(b.period)||13)))+1),n=1-a;let l=0,i=1,c=!0,s=!0;const f=new Array(t.length).fill(NaN),u=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++){const p=t[e].close,d=Number.isFinite(p)?p:0;s?(l=d,s=!1):l=a*d+n*l;let o;if(c){i*=n;const N=i>1e-10?1/(1-i):1;o=l*N,i<=1e-10&&(c=!1)}else o=l;const h=t[e].high,m=t[e].low;Number.isFinite(h)&&(f[e]=h-o),Number.isFinite(m)&&(u[e]=m-o)}return{bull:r(f),bear:r(u)}}})}export{g as default};
